"use client";

import { useState } from "react";
import { 
  Users, 
  UserPlus, 
  MoreVertical, 
  TrendingUp,
  User,
  Edit2,
  Trash2,
  Power
} from "lucide-react";
import { 
  CRMPageContainer, 
  CRMPageHeader, 
  CRMMetricsGrid, 
  MetricCard, 
  CRMCard,
  DataTable,
  CRMTableHeader,
  CRMTableBody,
  CRMTableRow,
  CRMTableCell,
  CRMTableHeaderCell,
  CRMToolbar,
  CRMStatusBadge,
  ActivityTimeline,
  CRMPageSection
} from "@/shared/components/crm";
import { Button } from "@/shared/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/shared/ui/avatar";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from "@/shared/ui/dropdown-menu";
import { 
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import { useEmployees, useToggleEmployeeStatus, useDeleteEmployee } from "@/shared/hooks/use-hrm";
// import { } from "@/shared/ui/progress";
import { toast } from "sonner";
import { FormModal } from "@/shared/components/form-modal";
import { EmployeesSkeleton } from "@/features/employees/components/EmployeesSkeleton";
import { EmployeeForm } from "@/features/forms/EmployeeForm";
import { useSearchParams } from "next/navigation";
import { useEffect } from "react";

const getSafeStr = (val: any) => (typeof val === 'string' ? val : typeof val === 'object' && val ? val.name || '' : String(val || ''));

export default function EmployeesPage() {
  const [searchQuery, setSearchQuery] = useState("");
  const { data: hrmData, isLoading: loading } = useEmployees();
  
  const employees = hrmData?.employees || [];
  const employeeStats = hrmData?.stats || [];
  const employeeActivities = hrmData?.recentActivities || [];
  
  const searchParams = useSearchParams();
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [isViewModalOpen, setIsViewModalOpen] = useState(false);
  const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [selectedEmployee, setSelectedEmployee] = useState<any>(null);

  const toggleStatusMutation = useToggleEmployeeStatus();
  const deleteMutation = useDeleteEmployee();

  useEffect(() => {
    if (searchParams.get("new") === "true") {
      // Avoid synchronous setState during render/effect cycle that might cause cascading renders
      const timer = setTimeout(() => {
        setIsAddModalOpen(true);
        const newUrl = window.location.pathname;
        window.history.replaceState({}, "", newUrl);
      }, 0);
      return () => clearTimeout(timer);
    }
  }, [searchParams]);

  const filteredEmployees = employees.filter(emp => {
    const nameMatch = getSafeStr(emp.name).toLowerCase().includes(searchQuery.toLowerCase());
    const emailMatch = getSafeStr(emp.email).toLowerCase().includes(searchQuery.toLowerCase());
    const roleMatch = getSafeStr(emp.role).toLowerCase().includes(searchQuery.toLowerCase());
    return nameMatch || emailMatch || roleMatch;
  });

  if (loading) {
    return <EmployeesSkeleton />;
  }

  const handleAddEmployee = () => {
    setIsAddModalOpen(true);
  };

  return (
    <CRMPageContainer>
      <CRMPageHeader
        title="Employee Directory"
        subtitle="Manage your workforce, monitor performance, and track department growth."
        badge="HR Management"
        icon={Users}
        actions={[
          {
            label: "Add Employee",
            icon: UserPlus,
            onClick: handleAddEmployee,
            variant: "default",
          },
        ]}
      />

      {/* Stats Grid */}
      <CRMMetricsGrid>
        {employeeStats.map((stat, i) => (
          <MetricCard
            key={i}
            {...stat}
            delay={i * 0.1}
          />
        ))}
      </CRMMetricsGrid>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
        {/* Main Table Area */}
        <div className="lg:col-span-3 space-y-6">
          <CRMToolbar 
            searchQuery={searchQuery}
            setSearchQuery={setSearchQuery}
            placeholder="Search employees by name or department..."
          />

          <DataTable>
            <CRMTableHeader>
              <CRMTableRow>
                <CRMTableHeaderCell>Employee</CRMTableHeaderCell>
                <CRMTableHeaderCell>Role</CRMTableHeaderCell>
                <CRMTableHeaderCell>Status</CRMTableHeaderCell>
                <CRMTableHeaderCell>Joined Date</CRMTableHeaderCell>
                <CRMTableHeaderCell className="text-right">Actions</CRMTableHeaderCell>
              </CRMTableRow>
            </CRMTableHeader>
            <CRMTableBody>
              {filteredEmployees.map((emp) => (
                <CRMTableRow key={emp.id} className="cursor-default">
                  <CRMTableCell>
                    <div className="flex items-center gap-3">
                      <Avatar className="h-10 w-10 border-2 border-background shadow-sm">
                        <AvatarImage src={""} alt={emp.name} />
                        <AvatarFallback>{emp.name.charAt(0)}</AvatarFallback>
                      </Avatar>
                      <div>
                        <div className="font-bold text-sm tracking-tight">{emp.name}</div>
                        <div className="text-[10px] text-muted-foreground font-medium">{emp.email}</div>
                      </div>
                    </div>
                  </CRMTableCell>
                  <CRMTableCell>
                    <span className="text-sm font-semibold capitalize">{getSafeStr(emp.role).toLowerCase()}</span>
                  </CRMTableCell>
                  <CRMTableCell>
                    <CRMStatusBadge tone={emp.status === 'ACTIVE' ? 'success' : 'warning'}>
                      {emp.status}
                    </CRMStatusBadge>
                  </CRMTableCell>
                  <CRMTableCell>
                    <span className="text-sm text-muted-foreground">
                      {new Date(emp.createdAt).toLocaleDateString()}
                    </span>
                  </CRMTableCell>
                  <CRMTableCell className="text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-8 w-8">
                          <MoreVertical className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-48 rounded-xl p-1.5 shadow-elevated border-border bg-popover/95 backdrop-blur-xl">
                        <DropdownMenuItem onClick={() => { setSelectedEmployee(emp); setIsViewModalOpen(true); }} className="cursor-pointer py-2.5 rounded-xl group">
                          <User className="mr-3 h-4 w-4 text-muted-foreground group-hover:text-primary transition-colors" />
                          <span className="font-semibold text-sm">View Details</span>
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => { setSelectedEmployee(emp); setIsEditModalOpen(true); }} className="cursor-pointer py-2.5 rounded-xl group">
                          <Edit2 className="mr-3 h-4 w-4 text-muted-foreground group-hover:text-primary transition-colors" />
                          <span className="font-semibold text-sm">Edit Employee</span>
                        </DropdownMenuItem>
                        
                        <DropdownMenuSeparator />
                        
                        <DropdownMenuItem 
                          onClick={() => {
                            const newStatus = emp.status === "ACTIVE" ? "INACTIVE" : "ACTIVE";
                            toggleStatusMutation.mutate(
                              { id: emp.id, status: newStatus },
                              { onSuccess: () => toast.success(`Employee ${newStatus.toLowerCase()}d`) }
                            );
                          }}
                          className="cursor-pointer py-2.5 rounded-xl group"
                        >
                          <Power className="mr-3 h-4 w-4 text-muted-foreground group-hover:text-primary transition-colors" />
                          <span className="font-semibold text-sm">{emp.status === "ACTIVE" ? "Deactivate" : "Activate"}</span>
                        </DropdownMenuItem>
                        <DropdownMenuItem 
                          variant="destructive"
                          onClick={() => { setSelectedEmployee(emp); setIsDeleteModalOpen(true); }}
                          className="cursor-pointer py-2.5 rounded-xl group"
                        >
                          <Trash2 className="mr-3 h-4 w-4 transition-colors" />
                          <span className="font-bold text-sm transition-colors">Delete Employee</span>
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </CRMTableCell>
                </CRMTableRow>
              ))}
            </CRMTableBody>
          </DataTable>
        </div>

        {/* Sidebar */}
        <div className="space-y-8">
          <CRMPageSection title="Recent Activity">
            <CRMCard className="p-6">
              <ActivityTimeline items={employeeActivities} />
              <Button variant="ghost" className="w-full mt-6 text-[10px] font-bold uppercase tracking-widest text-primary h-9">
                View All Activity
              </Button>
            </CRMCard>
          </CRMPageSection>

          <CRMPageSection title="Performance Overview">
            <CRMCard className="p-5 space-y-4">
              <div className="flex items-center justify-between">
                <div className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Top Dept</div>
                <TrendingUp className="w-4 h-4 text-emerald-500" />
              </div>
              <div>
                <h4 className="text-lg font-bold tracking-tight">Sales Team</h4>
                <p className="text-[10px] text-muted-foreground font-medium uppercase tracking-wider">Average Performance: 96%</p>
              </div>
              <div className="pt-2 border-t border-border/50">
                <div className="flex items-center gap-3">
                  <div className="flex -space-x-2">
                    {[1, 2, 3].map(i => (
                      <Avatar key={i} className="h-6 w-6 border-2 border-background">
                        <AvatarImage src={`https://i.pravatar.cc/150?u=${i}`} />
                      </Avatar>
                    ))}
                  </div>
                  <span className="text-[10px] font-bold text-muted-foreground">+5 more</span>
                </div>
              </div>
              <Button className="w-full h-9 bg-primary/10 hover:bg-primary/20 text-primary border-none text-xs font-bold">
                Analytics Report
              </Button>
            </CRMCard>
          </CRMPageSection>
        </div>
      </div>

      <FormModal
        title="Onboard New Employee"
        description="Add a new team member to your organization."
        isOpen={isAddModalOpen}
        onOpenChange={setIsAddModalOpen}
        size="lg"
      >
        <EmployeeForm 
          onSuccess={() => setIsAddModalOpen(false)} 
          onCancel={() => setIsAddModalOpen(false)} 
        />
      </FormModal>

      <FormModal
        title="Edit Employee"
        description="Update employee details and roles."
        isOpen={isEditModalOpen}
        onOpenChange={setIsEditModalOpen}
        size="lg"
      >
        {selectedEmployee && (
          <EmployeeForm 
            initialData={selectedEmployee}
            onSuccess={() => setIsEditModalOpen(false)} 
            onCancel={() => setIsEditModalOpen(false)} 
          />
        )}
      </FormModal>

      <FormModal
        title="Employee Details"
        description="Read-only view of employee information."
        isOpen={isViewModalOpen}
        onOpenChange={setIsViewModalOpen}
        size="md"
      >
        {selectedEmployee && (
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase">Name</label>
                <div className="font-medium">{selectedEmployee.name}</div>
              </div>
              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase">Email</label>
                <div className="font-medium">{selectedEmployee.email}</div>
              </div>
              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase">Role</label>
                <div className="font-medium capitalize">{getSafeStr(selectedEmployee.role).toLowerCase()}</div>
              </div>
              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase">Status</label>
                <div>
                  <CRMStatusBadge tone={selectedEmployee.status === 'ACTIVE' ? 'success' : 'warning'}>
                    {selectedEmployee.status}
                  </CRMStatusBadge>
                </div>
              </div>
              <div>
                <label className="text-xs font-bold text-muted-foreground uppercase">Joined Date</label>
                <div className="font-medium">{new Date(selectedEmployee.createdAt).toLocaleDateString()}</div>
              </div>
            </div>
            <div className="flex justify-end pt-4 border-t border-border mt-6">
              <Button onClick={() => setIsViewModalOpen(false)}>Close</Button>
            </div>
          </div>
        )}
      </FormModal>

      <AlertDialog open={isDeleteModalOpen} onOpenChange={setIsDeleteModalOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This action cannot be undone. This will permanently delete {selectedEmployee?.name}&apos;s account and remove their data from our servers.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction 
              onClick={() => {
                deleteMutation.mutate(selectedEmployee?.id, {
                  onSuccess: () => {
                    toast.success("Employee deleted permanently");
                    setIsDeleteModalOpen(false);
                  }
                });
              }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {deleteMutation.isPending ? "Deleting..." : "Delete Employee"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </CRMPageContainer>
  );
}

"use client";

import { useState } from "react";
import { Search, Plus, MoreHorizontal, Pencil, Trash2, ShieldCheck, AlertTriangle } from "lucide-react";
import { 
  DataTable,
  CRMTableHeader,
  CRMTableBody,
  CRMTableRow,
  CRMTableCell,
  CRMTableHeaderCell,
} from "@/shared/components/crm";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { toast } from "sonner";
import { RoleManagementSkeleton } from "../RoleManagementSkeleton";
import { Badge } from "@/shared/ui/badge";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useDebounce } from "@/hooks/use-debounce";
import { useAuth } from "@/features/auth/components/auth-provider";
import { Checkbox } from "@/shared/ui/checkbox";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/shared/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/shared/ui/dialog";

const MODULES = [
  "Dashboard", "CRM", "Leads", "Customers", "Contacts", "Pipeline", 
  "Tasks", "Meetings", "Employees", "Attendance", "Leave", "Payroll", 
  "Projects", "Reports", "Finance", "Settings"
];

export function RoleList() {
  const queryClient = useQueryClient();
  const [searchQuery, setSearchQuery] = useState("");
  const debouncedSearch = useDebounce(searchQuery, 300) || "";

  // Permissions editing state
  const [editingRoleId, setEditingRoleId] = useState<string | null>(null);
  const [editPermissions, setEditPermissions] = useState<string[]>([]);
  const [newRoleName, setNewRoleName] = useState("");

  // Rename dialog state
  const [renameDialogOpen, setRenameDialogOpen] = useState(false);
  const [renameTargetRole, setRenameTargetRole] = useState<any>(null);
  const [renameValue, setRenameValue] = useState("");

  // Delete dialog state
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleteTargetRole, setDeleteTargetRole] = useState<any>(null);

  const { user } = useAuth();
  const currentUserRole = user?.role?.toUpperCase() || "EMPLOYEE";
  const canEditAnyRole = currentUserRole === "SUPER ADMIN" || currentUserRole === "ADMIN";

  const { data, isLoading } = useQuery({
    queryKey: ['roles'],
    queryFn: async () => {
      const res = await fetch("/api/crm/roles");
      if (!res.ok) throw new Error("Failed to load roles");
      return res.json();
    }
  });

  // Save permissions mutation
  const saveMutation = useMutation({
    mutationFn: async ({ id, isNew, name }: { id: string; isNew: boolean, name?: string }) => {
      const url = isNew ? `/api/crm/roles` : `/api/crm/roles/${id}`;
      const method = isNew ? 'POST' : 'PUT';

      const payload: any = { permissions: editPermissions };
      if (isNew) {
        payload.name = name;
        payload.description = "";
      }

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || "Failed to save role");
      return data;
    },
    onSuccess: () => {
      toast.success("Role saved successfully");
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      setEditingRoleId(null);
    },
    onError: (err: any) => toast.error(err.message)
  });

  // Rename mutation
  const renameMutation = useMutation({
    mutationFn: async ({ id, name }: { id: string; name: string }) => {
      const res = await fetch(`/api/crm/roles/${id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || "Failed to rename role");
      return data;
    },
    onSuccess: () => {
      toast.success("Role renamed successfully");
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      setRenameDialogOpen(false);
      setRenameTargetRole(null);
    },
    onError: (err: any) => toast.error(err.message)
  });

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const res = await fetch(`/api/crm/roles/${id}`, { method: 'DELETE' });
      const data = await res.json();
      if (!res.ok) throw new Error(data.message || "Failed to delete role");
      return data;
    },
    onSuccess: () => {
      toast.success("Role deleted successfully");
      queryClient.invalidateQueries({ queryKey: ['roles'] });
      setDeleteDialogOpen(false);
      setDeleteTargetRole(null);
    },
    onError: (err: any) => toast.error(err.message)
  });

  if (isLoading) return <RoleManagementSkeleton />;

  const roles = data?.data || [];
  const filteredRoles = roles.filter((r: any) => {
    return r?.name?.toLowerCase().includes(debouncedSearch.toLowerCase());
  });

  const handleEditClick = (role: any) => {
    setEditingRoleId(role.id);
    const initialPerms: string[] = [];
    if (role.permissions && Array.isArray(role.permissions)) {
      role.permissions.forEach((rp: any) => {
        if (rp.hasAccess && rp.module) {
          initialPerms.push(rp.module);
        }
      });
    }
    setEditPermissions(initialPerms);
  };

  const handleCreateClick = () => {
    setEditingRoleId("new");
    setNewRoleName("");
    setEditPermissions([]);
  };

  const handleRenameClick = (role: any) => {
    setRenameTargetRole(role);
    setRenameValue(role.name);
    setRenameDialogOpen(true);
  };

  const handleDeleteClick = (role: any) => {
    setDeleteTargetRole(role);
    setDeleteDialogOpen(true);
  };

  const handleToggle = (module: string, checked: boolean) => {
    setEditPermissions((prev) => {
      if (checked) {
        return Array.from(new Set([...prev, module]));
      } else {
        return prev.filter((m: string) => m !== module);
      }
    });
  };

  const getModuleBadges = (role: any) => {
    if (!role.permissions) return [];
    return Array.from(new Set(role.permissions.filter((rp: any) => rp.hasAccess).map((rp: any) => rp.module).filter(Boolean))) as string[];
  };

  const renderInlinePermissionsEditor = () => (
    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-y-3 gap-x-4 py-2 max-h-[300px] overflow-y-auto w-full">
      {MODULES.map(module => (
        <label key={module} className="flex items-center gap-2 text-sm text-foreground cursor-pointer hover:bg-muted/50 p-1.5 rounded-md transition-colors">
          <Checkbox 
            className="w-4 h-4"
            checked={editPermissions.includes(module)}
            onCheckedChange={(c) => handleToggle(module, !!c)}
          />
          {module}
        </label>
      ))}
    </div>
  );

  return (
    <>
      <div className="space-y-6">
        <div className="flex justify-between items-center bg-card p-4 rounded-lg border">
          <div className="relative w-72">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input 
              placeholder="Search roles..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
          </div>
          <div className="flex items-center gap-2">
            {canEditAnyRole && editingRoleId !== "new" && (
              <Button onClick={handleCreateClick}>
                <Plus className="mr-2 h-4 w-4" /> Add Role
              </Button>
            )}
          </div>
        </div>

        <div className="border rounded-lg bg-card">
          <DataTable>
            <CRMTableHeader>
              <CRMTableRow>
                <CRMTableHeaderCell className="w-[22%]">Role Name</CRMTableHeaderCell>
                <CRMTableHeaderCell className="w-[55%]">Permissions</CRMTableHeaderCell>
                <CRMTableHeaderCell className="w-[10%]">Status</CRMTableHeaderCell>
                <CRMTableHeaderCell className="w-[13%] text-right">Actions</CRMTableHeaderCell>
              </CRMTableRow>
            </CRMTableHeader>
            <CRMTableBody>
              {editingRoleId === "new" && (
                <CRMTableRow className="bg-muted/10">
                  <CRMTableCell className="align-top pt-4">
                    <Input 
                      value={newRoleName}
                      onChange={(e) => setNewRoleName(e.target.value)}
                      placeholder="Enter role name"
                      className="max-w-[200px]"
                      autoFocus
                    />
                  </CRMTableCell>
                  <CRMTableCell className="align-top p-4">
                    {renderInlinePermissionsEditor()}
                  </CRMTableCell>
                  <CRMTableCell className="align-top pt-4">
                    <Badge variant="outline">New</Badge>
                  </CRMTableCell>
                  <CRMTableCell className="align-top pt-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <Button 
                        size="sm" 
                        onClick={() => {
                          if (!newRoleName.trim()) {
                            toast.error("Role name is required");
                            return;
                          }
                          saveMutation.mutate({ id: "new", isNew: true, name: newRoleName });
                        }}
                        disabled={saveMutation.isPending}
                      >
                        Save
                      </Button>
                      <Button size="sm" variant="outline" onClick={() => setEditingRoleId(null)} disabled={saveMutation.isPending}>
                        Cancel
                      </Button>
                    </div>
                  </CRMTableCell>
                </CRMTableRow>
              )}

              {filteredRoles.length === 0 && editingRoleId !== "new" ? (
                <CRMTableRow>
                  <CRMTableCell colSpan={4} className="text-center py-8 text-muted-foreground">
                    No roles found
                  </CRMTableCell>
                </CRMTableRow>
              ) : (
                filteredRoles.map((role: any) => {
                  const isSuperAdminTarget = role.name.toUpperCase() === "SUPER ADMIN";
                  const canEditThisRole = canEditAnyRole && !(currentUserRole === "ADMIN" && isSuperAdminTarget);
                  const canDeleteThisRole = canEditThisRole && !role.isSystem;
                  const roleIsActive = role.isSystem ? true : role.isActive;
                  const isEditingThisRow = editingRoleId === role.id;
                  const modules = getModuleBadges(role);

                  return (
                    <CRMTableRow key={role.id} className={isEditingThisRow ? "bg-muted/10" : ""}>
                      <CRMTableCell className="align-top pt-4">
                        <div className="flex items-center gap-2 font-medium">
                          <div className="w-2.5 h-2.5 rounded-full flex-shrink-0" style={{ backgroundColor: role.color || '#3b82f6' }} />
                          <span>{role.name}</span>
                          {role.isSystem && (
                            <Badge variant="secondary" className="ml-1 text-[9px] uppercase tracking-wider py-0 px-1">System</Badge>
                          )}
                        </div>
                      </CRMTableCell>
                      <CRMTableCell className="align-top pt-4">
                        {isEditingThisRow ? (
                          renderInlinePermissionsEditor()
                        ) : (
                          <div className="flex flex-wrap gap-1.5">
                            {modules.length === 0 ? (
                              <span className="text-sm text-muted-foreground">No permissions assigned</span>
                            ) : (
                              <>
                                {modules.slice(0, 4).map(m => (
