        ...(data.description !== undefined && { description: data.description }),
        ...(data.dueDate !== undefined && { dueDate: data.dueDate ? new Date(data.dueDate) : null }),
        ...(data.priority && { priority: data.priority }),
        ...(data.status && { status: data.status }),
      }
    });
    return task;
  }

